declare(strict_types=1);ini_set('display_errors','0');require dirname(__DIR__).'/private/app.php';require dirname(__DIR__).'/private/planning/core.php';security_headers();header('Cache-Control: private, no-store');header('X-Robots-Tag: noindex,nofollow');header('Content-Type: application/json; charset=utf-8');
try{$write=$_SERVER['REQUEST_METHOD']==='POST';current_session($write);pl_gate();rate('owner-planning',120);$r=$_GET['r']??'state';if(!$write&&$r==='state'){$c=pl_calendar();$tasks=pl_tasks();json_response(['ok'=>true,'calendar'=>$c?:null,'tasks'=>$tasks,'source_hash'=>$c?pl_hash($c,$tasks):null,'latest'=>crm_query('SELECT id FROM nd_workload_plans ORDER BY id DESC LIMIT 1')->fetchColumn()?:null]);}if(!$write&&$r==='plan')json_response(['ok'=>true,'plan'=>pl_plan(cc_id(filter_var($_GET['id']??'',FILTER_VALIDATE_INT)))]);if(!$write&&$r==='terms')json_response(['ok'=>true,'source'=>pl_terms_source(cc_id(filter_var($_GET['id']??'',FILTER_VALIDATE_INT)),cc_id(filter_var($_GET['order']??'',FILTER_VALIDATE_INT)))]);if($write){$d=input();json_response(match($r){'calendar'=>pl_save_calendar($d),'task'=>pl_save_task($d),'build'=>pl_build($d),'apply'=>pl_apply($d),default=>throw new CrmFailure(404,'Действие не найдено.')});}crm_fail(404,'Раздел не найден.');}catch(CrmFailure $e){fail($e->status,$e->getMessage(),'planning_error');}catch(CustomerFailure $e){fail($e->status,$e->getMessage(),$e->errorCode);}catch(Throwable $e){server_error($e);}
